        Container width: {width}px
        <input
          type='range'
          min={160}
          max={520}
          value={width}
          onChange={(e) => setWidth(Number(e.target.value))}
          style={{ accentColor: '#648aff' }}
        />
      </label>
      <span role='status' style={{ color: '#b8b8b8', fontSize: 13 }}>
