'use client';

import { useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { focusMenuItem, handleMenuKeys } from './menu-keys';
import { useDismiss } from './use-dismiss';
import './breadcrumb-collapse.css';

export interface Crumb {
  id: string;
  label: string;
}

export interface BreadcrumbCollapseProps {
  /** From the root to the current page. The last item is the current page. */
  items: Crumb[];
  onNavigate: (id: string) => void;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * When the trail is too wide, middle crumbs fold into a "…" menu. The first
 * crumb and the current page always stay visible. Crumbs slide back in as
 * room returns.
 */
export function BreadcrumbCollapse({
  items,
  onNavigate,
  className = '',
}: BreadcrumbCollapseProps) {
  const root = useRef<HTMLElement>(null);
  const measure = useRef<HTMLOListElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const popup = useRef<HTMLLIElement>(null);
  const [hidden, setHidden] = useState(0);
  const [open, setOpen] = useState(false);
  const id = useId();

  useIsomorphicLayoutEffect(() => {
    const nav = root.current;
    const row = measure.current;
    if (!nav || !row) return;
    const fit = () => {
      const widths = Array.from(row.children).map(
        (child) => (child as HTMLElement).offsetWidth
      );
      const ellipsis = widths[widths.length - 1];
      const crumbs = widths.slice(0, -1);
      const available = nav.clientWidth;
      let collapse = 0;
      const total = (n: number) =>
        crumbs.reduce((sum, w, i) => (i > 0 && i <= n ? sum : sum + w), 0) +
        (n > 0 ? ellipsis : 0);
      while (collapse < items.length - 2 && total(collapse) > available)
        collapse += 1;
      setHidden(collapse);
    };
    fit();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(fit);
    observer.observe(nav);
    return () => observer.disconnect();
  }, [items]);

  useEffect(() => {
    if (open) focusMenuItem(menu.current);
  }, [open]);
  useEffect(() => {
    if (hidden === 0) setOpen(false);
  }, [hidden]);

  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) trigger.current?.focus();
  };
  useDismiss(open, [popup], (reason) => close(reason === 'escape'));

  const collapsed = items.slice(1, 1 + hidden);
  const visible = items.filter((_, i) => i === 0 || i > hidden);

  return (
    <nav
      ref={root}
      aria-label='Breadcrumb'
      className={`mg-crumbs ${className}`}
    >
      <ol ref={measure} className='mg-crumbs__measure' aria-hidden='true'>
        {items.map((item) => (
          <li key={item.id} className='mg-crumbs__item'>
            <span className='mg-crumbs__link'>{item.label}</span>
          </li>
        ))}
        <li className='mg-crumbs__item'>
          <span className='mg-crumbs__more'>…</span>
        </li>
      </ol>
      <ol className='mg-crumbs__list'>
        {visible.map((item, index) => {
          const current = item.id === items[items.length - 1].id;
          return [
            index === 1 && hidden > 0 ? (
              <li
                key='more'
                ref={popup}
                className='mg-crumbs__item mg-crumbs__item--more'
              >
                <button
                  ref={trigger}
                  type='button'
                  className='mg-crumbs__more'
                  aria-label={`Show ${hidden} hidden ${hidden === 1 ? 'level' : 'levels'}`}
                  aria-haspopup='menu'
                  aria-expanded={open}
                  aria-controls={id}
                  onClick={() => setOpen((value) => !value)}
                >
                  …
                </button>
                <div
                  ref={menu}
                  id={id}
                  role='menu'
                  className='mg-crumbs__menu'
                  hidden={!open}
                  onKeyDown={(event) => {
                    if (event.key === 'Tab') close(false);
                    else handleMenuKeys(event, menu.current);
                  }}
                >
                  {collapsed.map((crumb) => (
                    <button
                      key={crumb.id}
                      type='button'
                      role='menuitem'
                      tabIndex={-1}
                      onClick={() => {
                        close(true);
                        onNavigate(crumb.id);
                      }}
                    >
                      {crumb.label}
                    </button>
                  ))}
                </div>
              </li>
            ) : null,
            <li
              key={item.id}
              className='mg-crumbs__item'
              data-enter={index > 0}
            >
              {current ? (
                <span className='mg-crumbs__link' aria-current='page'>
                  {item.label}
                </span>
              ) : (
                <button
                  type='button'
                  className='mg-crumbs__link'
                  onClick={() => onNavigate(item.id)}
                >
                  {item.label}
                </button>
              )}
            </li>,
          ];
        })}
      </ol>
    </nav>
  );
}

.mg-crumbs {
  position: relative;
  min-width: 0;
  color: var(--mg-text, #ffffff);
}

.mg-crumbs__list,
.mg-crumbs__measure {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 0;
  list-style: none;
  white-space: nowrap;
}

/* Every crumb at full width, measured but never seen. */
.mg-crumbs__measure {
  position: absolute;
  visibility: hidden;
  pointer-events: none;
}

.mg-crumbs__item {
  position: relative;
  display: flex;
  align-items: center;
}

.mg-crumbs__item + .mg-crumbs__item::before {
  margin: 0 4px;
  color: #8f8f8f;
  content: '/';
}

.mg-crumbs__item[data-enter='true'] {
  animation: mg-crumbs-in 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-crumbs__link,
.mg-crumbs__more {
  min-height: 40px;
  padding: 0 6px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: inherit;
  font: inherit;
  line-height: 40px;
}

button.mg-crumbs__link,
button.mg-crumbs__more {
  color: var(--mg-accent-text, #648aff);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.mg-crumbs__more {
  min-width: 36px;
  text-decoration: none !important;
}

.mg-crumbs__link[aria-current='page'] {
  font-weight: 700;
}

.mg-crumbs__link:focus-visible,
.mg-crumbs__more:focus-visible,
.mg-crumbs__menu button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 1px;
}

.mg-crumbs__menu {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 10;
  display: grid;
  min-width: 160px;
  padding: 6px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 10px;
  background: #121212;
  box-shadow: 0 14px 28px -14px rgba(0, 0, 0, 0.45);
  animation: mg-crumbs-menu 160ms ease-out;
}

.mg-crumbs__menu[hidden] {
  display: none;
}

.mg-crumbs__menu button {
  min-height: 40px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--mg-text, #ffffff);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.mg-crumbs__menu button:hover,
.mg-crumbs__menu button:focus {
  background: #141d38;
}

@keyframes mg-crumbs-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
}

@keyframes mg-crumbs-menu {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-crumbs__item[data-enter='true'],
  .mg-crumbs__menu {
    animation: none;
  }
}

const ITEM =
  '[role="menuitem"]:not([aria-disabled="true"]), [role="menuitemradio"], [role="menuitemcheckbox"]';

function items(menu: HTMLElement) {
  return Array.from(menu.querySelectorAll<HTMLElement>(ITEM)).filter(
    (item) => item.closest('[role="menu"]') === menu
  );
}

/** Moves focus to the first (or last) item of `menu`. */
export function focusMenuItem(
  menu: HTMLElement | null,
  which: 'first' | 'last' = 'first'
) {
  if (!menu) return;
  const list = items(menu);
  list[which === 'first' ? 0 : list.length - 1]?.focus();
}

/**
 * Arrow, Home and End navigation between the items of `menu`. Call it from
 * the menu's keydown handler. Returns true when the key was handled.
 */
export function handleMenuKeys(
  event: { key: string; preventDefault(): void },
  menu: HTMLElement | null
): boolean {
  if (!menu) return false;
  const list = items(menu);
  if (list.length === 0) return false;
  const index = list.indexOf(document.activeElement as HTMLElement);
  let next: number;
  switch (event.key) {
    case 'ArrowDown':
      next = (index + 1) % list.length;
      break;
    case 'ArrowUp':
      next = index <= 0 ? list.length - 1 : index - 1;
      break;
    case 'Home':
      next = 0;
      break;
    case 'End':
      next = list.length - 1;
      break;
    default:
      return false;
  }
  event.preventDefault();
  list[next].focus();
  return true;
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

export type DismissReason = 'escape' | 'outside';

/**
 * While `active`, calls `onDismiss` when Escape is pressed or when a pointer
 * goes down outside every element in `refs`. Decide where focus goes in
 * `onDismiss`: back to the trigger after Escape, left alone after an
 * outside press.
 */
export function useDismiss(
  active: boolean,
  refs: RefObject<HTMLElement | null>[],
  onDismiss: (reason: DismissReason) => void
) {
  const callback = useRef(onDismiss);
  callback.current = onDismiss;
  const inside = useRef(refs);
  inside.current = refs;

  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      callback.current('escape');
    };
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (inside.current.some((ref) => ref.current?.contains(target))) return;
      callback.current('outside');
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('pointerdown', onPointerDown);
    };
  }, [active]);
}
